import {t} from './i18n.js?v=rig4';
import {escapeHtml as e} from './config.js?v=rig4';
import {createResumeDialog} from './content.js?v=rig4';
export function createGameUI(container,engine,getConfig){
 const overlay=document.createElement('div');overlay.className='game-ui';container.appendChild(overlay);const visited=new Set();let current=null;
 const modal=createResumeDialog(getConfig,paused=>{if(engine){engine.paused=paused;engine.release();}});
 function open(id){if(['skills','experience','education','projects'].includes(id))visited.add(id);modal.open(id);updateProgress();}
 function updateProgress(){const n=overlay.querySelector('.game-progress');if(n)n.textContent=`${visited.size} / 4`;overlay.querySelectorAll('[data-game-section]').forEach(b=>b.classList.toggle('visited',visited.has(b.dataset.gameSection)));}
 function render(){const c=getConfig(),lang=c.language;overlay.dir=lang==='he'?'rtl':'ltr';overlay.innerHTML=`<div class="game-top"><div class="game-identity"><span class="game-monogram">${e(c.profile.name.slice(0,1)||'P')}</span><div><strong dir="auto">${e(c.profile.name)}</strong><small dir="auto">${e(c.profile.role)}</small></div></div><button class="game-resume" data-game-section="all">${t(lang,'readResume')} ↗</button></div><nav class="game-sections" aria-label="${t(lang,'story')}">${['skills','experience','education','projects'].map((id,i)=>`<button data-game-section="${id}"><span>0${i+1}</span>${t(lang,id)}<span class="game-check">↗</span></button>`).join('')}<div class="game-explored">${t(lang,'explored')}<b class="game-progress">0 / 4</b></div></nav><div class="game-minimap"><canvas width="180" height="180" aria-label="${lang==='he'?'מפת העולם':'World map'}"></canvas><span>N</span></div><div class="game-controls"><span><kbd>W A S D</kbd> ${t(lang,'move')}</span><span><kbd>SHIFT</kbd> ${t(lang,'sprint')}</span><span><kbd>SPACE</kbd> ${t(lang,'jump')}</span><span>↔ ${t(lang,'look')}</span><button class="game-reset" aria-label="${t(lang,'reset')}">↺</button></div><div class="game-enter" hidden><kbd>↵</kbd><div><small>${t(lang,'enter')}</small><strong></strong></div><button>${t(lang,'explore')} ↗</button></div><div class="game-touch"><div class="game-dpad"><button data-move="forward" aria-label="${lang==='he'?'קדימה':'Forward'}">↑</button><button data-move="left" aria-label="${lang==='he'?'שמאלה':'Turn left'}">←</button><button data-move="back" aria-label="${lang==='he'?'אחורה':'Back'}">↓</button><button data-move="right" aria-label="${lang==='he'?'ימינה':'Turn right'}">→</button></div><button class="game-jump">↑<small>${t(lang,'jump')}</small></button></div><span class="game-sample">${c.isSample?t(lang,'sampleGame'):''}</span>`;
  overlay.querySelectorAll('[data-game-section]').forEach(b=>b.onclick=()=>open(b.dataset.gameSection));overlay.querySelector('.game-enter button').onclick=()=>current&&open(current.id);overlay.querySelector('.game-reset').onclick=()=>engine?.setMode('play');overlay.querySelector('.game-jump').onclick=()=>engine?.doJump();
  overlay.querySelectorAll('[data-move]').forEach(b=>{b.addEventListener('pointerdown',ev=>{ev.preventDefault();b.setPointerCapture(ev.pointerId);engine?.keys.add(b.dataset.move)});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>engine?.keys.delete(b.dataset.move));});updateProgress();setNear(current);
 }
 function setNear(station){current=station;const el=overlay.querySelector('.game-enter');el.hidden=!station;if(station)el.querySelector('strong').textContent=t(getConfig().language,station.id);}
 function minimap({x,z,yaw,stations}){const canvas=overlay.querySelector('.game-minimap canvas');if(!canvas)return;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,180,180);ctx.fillStyle='#20313f';ctx.fillRect(0,0,180,180);ctx.fillStyle='#6a7884';ctx.fillRect(80,10,20,160);const px=x=>90+x*2.3,pz=z=>140+z*1.9;for(const s of stations){ctx.fillStyle=s.color;ctx.fillRect(px(s.x)-5,pz(s.z)-4,10,8);}ctx.save();ctx.translate(px(x),pz(z));ctx.rotate(-yaw);ctx.fillStyle='#fff';ctx.beginPath();ctx.moveTo(0,-6);ctx.lineTo(4,5);ctx.lineTo(0,3);ctx.lineTo(-4,5);ctx.fill();ctx.restore();}
 if(engine){engine.options.onNear=setNear;engine.options.onOpen=open;engine.options.onMove=minimap;}render();
 return {render,open,modal,overlay,setVisible(visible){overlay.hidden=!visible;if(!visible&&modal.element.open)modal.close();},destroy(){overlay.remove();modal.destroy();}};
}
